    public function isViewable(array $file)
    {
        return \in_array($this->getExtensions($file), self::VIEWABLE_FILE, true);
    }

    public function getExtensions(array $file): string
    {
        if (\array_key_exists('extension', $file)) {
            return $file['extension'];
        }

        if (\array_key_exists('filePath', $file)) {
            return pathinfo($file['filePath'], \PATHINFO_EXTENSION);
        }

        throw new \RuntimeException('No extension found');
    }

    public function getBootstrapSvg(array $file): string
    {
        return self::BOOTSTRAP_SVG[$this->getExtensions($file)] ?? self::BOOTSTRAP_SVG['default'];
    }
}
